// src/notification-scheduler.ts
function createNotificationScheduler(resolvedConfig) {
  const pendingBySession = new Map;
  const schedule = (sessionId, title, message, eventType) => {
    if (eventType && !resolvedConfig.isEnabled(eventType)) {
      return;
    }
    const existing = pendingBySession.get(sessionId);
    if (existing) {
      clearTimeout(existing.timeoutId);
    }
    const delay = resolvedConfig.getDelay(eventType);
    const timeoutId = setTimeout(() => {
      Notification.notify({ title, message });
      pendingBySession.delete(sessionId);
    }, delay);
    pendingBySession.set(sessionId, { title, message, timeoutId });
  };
  const cancelForSession = (sessionId) => {
    const pending = pendingBySession.get(sessionId);
    if (pending) {
      clearTimeout(pending.timeoutId);
      pendingBySession.delete(sessionId);
    }
  };
  const cancelAll = () => {
    for (const pending of pendingBySession.values()) {
      clearTimeout(pending.timeoutId);
    }
    pendingBySession.clear();
  };
  return {
    schedule,
    cancelForSession,
    cancelAll
  };
}

